import { useCallback, useEffect, useMemo, useState } from 'react';
import { clsx } from 'clsx';
import { CheckCircle2, LayoutDashboard, Package, RotateCcw, ShoppingBag, Users } from 'lucide-react';
import { SHOP } from './data/catalog';
import { IMG } from './data/images';
import { TODAY } from './data/generate';
import { useStore } from './lib/store';
import { money, pct } from './lib/format';
import type { Period } from './lib/metrics';
import { Button, Modal } from './components/ui';
import Overview from './components/Overview';
import Orders from './components/Orders';
import OrderDrawer from './components/OrderDrawer';
import Products from './components/Products';
import Customers from './components/Customers';

type View = 'resumen' | 'pedidos' | 'productos' | 'clientes';

const NAV: Array<{ id: View; label: string; icon: typeof Users; title: string; hint: string }> = [
  { id: 'resumen', label: 'Resumen', icon: LayoutDashboard, title: 'Resumen de ventas', hint: 'Cómo va la tienda en el periodo elegido frente al anterior' },
  { id: 'pedidos', label: 'Pedidos', icon: ShoppingBag, title: 'Pedidos', hint: 'Busca, filtra y gestiona cada pedido' },
  { id: 'productos', label: 'Productos', icon: Package, title: 'Productos', hint: 'Qué se vende, cuánto deja y cuánto stock queda' },
  { id: 'clientes', label: 'Clientes', icon: Users, title: 'Clientes', hint: 'Quién compra, cuánto y cada cuánto' },
];

const MONTH_GOAL = 24_000;

const fromHash = (): View => {
  const v = window.location.hash.replace('#/', '') as View;
  return NAV.some(n => n.id === v) ? v : 'resumen';
};

function Logo() {
  return (
    <div className="flex items-center gap-2.5">
      <span className="grid h-8 w-8 place-items-center rounded-[10px] bg-[#C0283F]">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M2 13h4l2.5-6 4 11 3-8 1.5 3H22" />
        </svg>
      </span>
      <span className="display text-[21px] font-semibold">Pulso</span>
    </div>
  );
}

export default function App() {
  const store = useStore();
  const [view, setView] = useState<View>(fromHash);
  const [period, setPeriod] = useState<Period>(30);
  const [openId, setOpenId] = useState<string | null>(null);
  const [toast, setToast] = useState<string | null>(null);
  const [confirmReset, setConfirmReset] = useState(false);

  useEffect(() => {
    const h = () => setView(fromHash());
    window.addEventListener('hashchange', h);
    return () => window.removeEventListener('hashchange', h);
  }, []);

  const go = (v: View) => { setView(v); setOpenId(null); try { window.history.replaceState(null, '', `#/${v}`); } catch { /* vista previa */ } window.scrollTo(0, 0); };

  const notify = useCallback((msg: string) => {
    setToast(msg);
    window.setTimeout(() => setToast(t => (t === msg ? null : t)), 2600);
  }, []);

  const toPrepare = store.orders.filter(o => o.status === 'preparando' || o.status === 'pendiente').length;
  const monthStart = useMemo(() => { const d = new Date(TODAY); d.setDate(1); return d.getTime(); }, []);
  const monthRevenue = store.orders.filter(o => o.ts >= monthStart && o.status !== 'reembolsado').reduce((s, o) => s + o.total, 0);
  const goal = Math.min(1, monthRevenue / MONTH_GOAL);
  const current = NAV.find(n => n.id === view)!;
  const openOrder = store.orders.find(o => o.id === openId);
  const props = { store, period, openOrder: setOpenId, notify };

  return (
    <div className="pulso min-h-screen bg-[#EEF1F4] text-[#151A23]">
      {/* Barra lateral (escritorio) */}
      <aside className="fixed inset-y-0 left-0 z-30 hidden w-60 flex-col bg-[#151A23] px-4 py-5 text-white lg:flex">
        <div className="px-2"><Logo /></div>
        <div className="mt-6 rounded-xl bg-white/[0.06] px-3 py-2.5">
          <div className="text-sm font-medium">{SHOP.name}</div>
          <div className="text-xs text-white/55">{SHOP.domain}</div>
        </div>
        <nav className="mt-6 space-y-1" aria-label="Secciones">
          {NAV.map(n => (
            <button key={n.id} onClick={() => go(n.id)} aria-current={view === n.id ? 'page' : undefined}
              className={clsx('flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors',
                view === n.id ? 'bg-white text-[#151A23]' : 'text-white/70 hover:bg-white/[0.07] hover:text-white')}>
              <n.icon size={18} />
              <span className="flex-1 text-left">{n.label}</span>
              {n.id === 'pedidos' && toPrepare > 0 && (
                <span className={clsx('num rounded-full px-2 py-0.5 text-[11px] font-semibold', view === n.id ? 'bg-[#C0283F] text-white' : 'bg-white/10 text-white')}>{toPrepare}</span>
              )}
            </button>
          ))}
        </nav>
        <div className="mt-auto space-y-4">
          <div className="rounded-xl border border-white/10 p-3.5">
            <div className="flex items-baseline justify-between text-xs text-white/60"><span>Objetivo del mes</span><span className="num">{pct(goal, 0)}</span></div>
            <div className="num display mt-1 text-lg font-semibold">{money(monthRevenue, 0)}</div>
            <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white/10">
              <div className="bar-grow h-full rounded-full bg-[#E3A73B]" style={{ width: `${goal * 100}%` }} />
            </div>
            <div className="num mt-1.5 text-xs text-white/50">de {money(MONTH_GOAL, 0)}</div>
          </div>
          <div className="flex items-center gap-3 px-1">
            <img src={IMG('escritorio-1')} alt="Foto de Daniel Ortega" className="h-9 w-9 rounded-full bg-white/10 object-cover" />
            <div className="min-w-0 flex-1">
              <div className="truncate text-sm font-medium">Daniel Ortega</div>
              <div className="text-xs text-white/55">Fundador</div>
            </div>
            <button onClick={() => setConfirmReset(true)} aria-label="Restablecer datos de ejemplo" title="Restablecer datos de ejemplo"
              className="rounded-lg p-2 text-white/60 hover:bg-white/10 hover:text-white"><RotateCcw size={16} /></button>
          </div>
        </div>
      </aside>

      {/* Barra superior (móvil) */}
      <header className="sticky top-0 z-30 flex items-center justify-between bg-[#151A23] px-4 py-3 text-white lg:hidden">
        <Logo />
        <div className="flex items-center gap-2">
          <span className="text-sm text-white/70">{SHOP.name}</span>
          <button onClick={() => setConfirmReset(true)} aria-label="Restablecer datos de ejemplo" className="rounded-lg p-2 text-white/70 hover:bg-white/10"><RotateCcw size={16} /></button>
        </div>
      </header>

      <main className="px-4 pb-28 pt-5 sm:px-6 lg:ml-60 lg:px-8 lg:pb-10 lg:pt-7">
        <div className="mx-auto max-w-[1240px]">
          <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <h1 className="display text-[28px] font-semibold leading-tight sm:text-[32px]">{current.title}</h1>
              <p className="mt-1 text-sm text-[#5B6472]">{view === 'resumen' ? `Últimos ${period} días frente a los ${period} anteriores` : current.hint}</p>
            </div>
            <div role="tablist" aria-label="Periodo" className="inline-flex self-start rounded-xl border border-[#DFE3E9] bg-white p-1 sm:self-auto">
              {([7, 30, 90] as Period[]).map(p => (
                <button key={p} role="tab" aria-selected={period === p} onClick={() => setPeriod(p)}
                  className={clsx('num rounded-lg px-3.5 py-1.5 text-sm font-medium transition-colors',
                    period === p ? 'bg-[#151A23] text-white' : 'text-[#3D4552] hover:bg-[#EEF1F4]')}>
                  {p} días
                </button>
              ))}
            </div>
          </div>
          {view === 'resumen' && <Overview {...props} goTo={() => go('pedidos')} />}
          {view === 'pedidos' && <Orders {...props} />}
          {view === 'productos' && <Products {...props} />}
          {view === 'clientes' && <Customers {...props} />}
        </div>
      </main>

      {/* Navegación inferior (móvil) */}
      <nav className="fixed inset-x-0 bottom-0 z-30 grid grid-cols-4 border-t border-[#DFE3E9] bg-white/95 backdrop-blur lg:hidden" aria-label="Secciones">
        {NAV.map(n => (
          <button key={n.id} onClick={() => go(n.id)} aria-current={view === n.id ? 'page' : undefined}
            className={clsx('flex flex-col items-center gap-1 py-2.5 text-[11px] font-medium', view === n.id ? 'text-[#C0283F]' : 'text-[#5B6472]')}>
            <n.icon size={20} />{n.label}
          </button>
        ))}
      </nav>

      {openOrder && <OrderDrawer key={openOrder.id} order={openOrder} store={store} notify={notify} onClose={() => setOpenId(null)} />}

      {confirmReset && (
        <Modal title="Restablecer datos" onClose={() => setConfirmReset(false)}>
          <p className="text-sm text-[#3D4552]">Se borrarán los pedidos registrados a mano, los cambios de estado, las notas, los productos editados y los clientes añadidos. Volverás a ver los datos de ejemplo.</p>
          <div className="mt-6 flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setConfirmReset(false)}>Cancelar</Button>
            <Button onClick={() => { store.reset(); setConfirmReset(false); setOpenId(null); notify('Datos de ejemplo restablecidos'); }}>Restablecer</Button>
          </div>
        </Modal>
      )}

      {toast && (
        <div role="status" className="fixed inset-x-4 bottom-20 z-[60] flex justify-center lg:inset-x-auto lg:bottom-6 lg:right-6">
          <div className="pop flex items-center gap-2 rounded-xl bg-[#151A23] px-4 py-3 text-sm text-white shadow-xl">
            <CheckCircle2 size={18} className="text-[#7BD3A8]" />{toast}
          </div>
        </div>
      )}
    </div>
  );
}

import { useMemo, useState, type FormEvent } from 'react';
import { clsx } from 'clsx';
import { ChevronLeft, ChevronRight, Mail, MapPin, Search, UserPlus, UserSearch } from 'lucide-react';
import { CITIES, type Customer } from '../data/catalog';
import { TODAY } from '../data/generate';
import type { ViewProps } from '../lib/store';
import { customerStats, inPeriod, segmentOf, SEGMENT_STYLE, type Segment } from '../lib/metrics';
import { money, num, pct, relative, shortDate } from '../lib/format';
import { Avatar, Button, Card, Chips, Drawer, Empty, Field, Modal, StatusBadge, inputCls } from './ui';

const PAGE = 10;
const SEGMENTS: Segment[] = ['VIP', 'Recurrente', 'Nuevo', 'En riesgo', 'Sin compras'];

export default function Customers({ store, period, openOrder, notify }: ViewProps) {
  const [q, setQ] = useState('');
  const [seg, setSeg] = useState<Segment | 'todos'>('todos');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Customer | null>(null);
  const [adding, setAdding] = useState(false);

  const stats = useMemo(() => customerStats(store.orders), [store.orders]);
  const active = useMemo(() => customerStats(inPeriod(store.orders, period)), [store.orders, period]);
  const periodStart = TODAY - (period - 1) * 86_400_000;
  const newOnes = [...active.keys()].filter(id => (stats.get(id)?.first ?? 0) >= periodStart).length;
  const repeat = [...active.keys()].filter(id => (stats.get(id)?.count ?? 0) > 1).length;
  const activeSpent = [...active.values()].reduce((s, x) => s + x.spent, 0);

  const rows = useMemo(() => {
    const term = q.trim().toLowerCase();
    return store.customers
      .map(c => ({ c, s: stats.get(c.id), seg: segmentOf(stats.get(c.id)) }))
      .filter(r => (seg === 'todos' || r.seg === seg) && (!term || r.c.name.toLowerCase().includes(term) || r.c.email.includes(term) || r.c.city.toLowerCase().includes(term)))
      .sort((a, b) => (b.s?.spent ?? 0) - (a.s?.spent ?? 0));
  }, [store.customers, stats, q, seg]);
  const segCount = (s: Segment) => store.customers.filter(c => segmentOf(stats.get(c.id)) === s).length;

  const pages = Math.max(1, Math.ceil(rows.length / PAGE));
  const cur = Math.min(page, pages - 1);
  const history = selected ? store.orders.filter(o => o.customerId === selected.id) : [];

  const kpis = [
    { label: 'Clientes activos', value: num(active.size), hint: `compraron en ${period} días` },
    { label: 'Clientes nuevos', value: num(newOnes), hint: 'primer pedido en el periodo' },
    { label: 'Repiten compra', value: pct(active.size ? repeat / active.size : 0, 0), hint: 'de los clientes activos' },
    { label: 'Gasto medio', value: money(active.size ? activeSpent / active.size : 0), hint: 'por cliente activo' },
  ];

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        {kpis.map(k => (
          <Card key={k.label} className="px-5 py-4">
            <div className="text-sm text-[#5B6472]">{k.label}</div>
            <div className="num display mt-1.5 text-2xl font-semibold">{k.value}</div>
            <div className="mt-0.5 text-xs text-[#8A93A1]">{k.hint}</div>
          </Card>
        ))}
      </div>

      <div className="flex flex-col gap-3 md:flex-row md:items-center">
        <div className="relative flex-1">
          <Search size={17} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[#8A93A1]" />
          <input value={q} onChange={e => { setQ(e.target.value); setPage(0); }} placeholder="Buscar por nombre, email o ciudad" aria-label="Buscar clientes" className={`${inputCls} pl-9`} />
        </div>
        <Button onClick={() => setAdding(true)} className="h-10"><UserPlus size={16} />Añadir cliente</Button>
      </div>

      <Chips value={seg} onChange={v => { setSeg(v); setPage(0); }} options={[
        { id: 'todos', label: 'Todos', count: store.customers.length }, ...SEGMENTS.map(s => ({ id: s, label: s, count: segCount(s) })),
      ]} />

      <Card className="overflow-hidden">
        {rows.length === 0 ? (
          <Empty icon={<UserSearch size={22} />} title="No encontramos a ese cliente" text="Comprueba cómo se escribe o añádelo para registrar sus pedidos." />
        ) : (
          <ul className="divide-y divide-[#EEF0F3]">
            {rows.slice(cur * PAGE, cur * PAGE + PAGE).map(({ c, s, seg: sg }) => (
              <li key={c.id}>
                <button onClick={() => setSelected(c)} className="grid w-full grid-cols-[minmax(0,1fr)_auto] items-center gap-4 px-5 py-3 text-left hover:bg-[#F7F8FA] md:grid-cols-[minmax(0,2fr)_1fr_0.7fr_1fr_1fr_110px]">
                  <span className="flex min-w-0 items-center gap-3">
                    <Avatar c={c} />
                    <span className="min-w-0">
                      <span className="block truncate text-sm font-medium">{c.name}</span>
                      <span className="block truncate text-xs text-[#5B6472]">{c.email}</span>
                    </span>
                  </span>
                  <span className="hidden text-sm text-[#3D4552] md:block">{c.city}</span>
                  <span className="num hidden text-sm md:block">{num(s?.count ?? 0)} ped.</span>
                  <span className="num hidden text-sm font-semibold md:block">{money(s?.spent ?? 0, 0)}</span>
                  <span className="hidden text-sm text-[#5B6472] md:block">{s ? relative(s.last) : '—'}</span>
                  <span className={clsx('justify-self-end whitespace-nowrap rounded-full px-2.5 py-0.5 text-xs font-medium', SEGMENT_STYLE[sg])}>{sg}</span>
                </button>
              </li>
            ))}
          </ul>
        )}
        <div className="flex items-center justify-between border-t border-[#E6E9EE] px-5 py-3 text-sm text-[#5B6472]">
          <span className="num">{rows.length ? `${cur * PAGE + 1}–${Math.min(rows.length, (cur + 1) * PAGE)} de ${num(rows.length)}` : '0 clientes'}</span>
          <div className="flex gap-1">
            <button disabled={cur === 0} onClick={() => setPage(cur - 1)} aria-label="Página anterior" className="rounded-lg p-1.5 hover:bg-[#EEF1F4] disabled:opacity-30"><ChevronLeft size={18} /></button>
            <button disabled={cur >= pages - 1} onClick={() => setPage(cur + 1)} aria-label="Página siguiente" className="rounded-lg p-1.5 hover:bg-[#EEF1F4] disabled:opacity-30"><ChevronRight size={18} /></button>
          </div>
        </div>
      </Card>

      {selected && (
        <Drawer onClose={() => setSelected(null)} title={selected.name} subtitle={`Cliente desde ${shortDate(TODAY - selected.since * 86_400_000)} ${new Date(TODAY - selected.since * 86_400_000).getFullYear()}`}>
          <div className="flex items-center gap-4">
            <Avatar c={selected} size={56} />
            <div className="space-y-1 text-sm text-[#3D4552]">
              <div className="flex items-center gap-2"><Mail size={15} className="text-[#8A93A1]" />{selected.email}</div>
              <div className="flex items-center gap-2"><MapPin size={15} className="text-[#8A93A1]" />{selected.city}</div>
            </div>
          </div>
          <div className="num mt-5 grid grid-cols-3 gap-2 text-center">
            {[['Pedidos', num(stats.get(selected.id)?.count ?? 0)], ['Gastado', money(stats.get(selected.id)?.spent ?? 0, 0)],
              ['Ticket medio', money(stats.get(selected.id) ? stats.get(selected.id)!.spent / stats.get(selected.id)!.count : 0, 0)]].map(([l, v]) => (
              <div key={l} className="rounded-xl bg-[#F4F6F8] px-2 py-3"><div className="display text-lg font-semibold">{v}</div><div className="text-xs text-[#5B6472]">{l}</div></div>
            ))}
          </div>
          <h3 className="display mb-2 mt-6 text-[15px] font-semibold">Historial de pedidos</h3>
          {history.length === 0 ? <p className="text-sm text-[#5B6472]">Todavía no ha comprado. Registra su primer pedido desde la sección Pedidos.</p> : (
            <ul className="-mx-2">
              {history.map(o => (
                <li key={o.id}>
                  <button onClick={() => { setSelected(null); openOrder(o.id); }} className="flex w-full items-center gap-3 rounded-lg px-2 py-2.5 text-left hover:bg-[#F4F6F8]">
                    <div className="min-w-0 flex-1"><div className="text-sm font-medium">{o.id}</div><div className="text-xs text-[#5B6472]">{relative(o.ts)} · {o.items.length} {o.items.length === 1 ? 'artículo' : 'artículos'}</div></div>
                    <StatusBadge status={o.status} />
                    <span className="num w-20 text-right text-sm font-semibold">{money(o.total)}</span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </Drawer>
      )}

      {adding && <NewCustomer existing={store.customers} onClose={() => setAdding(false)} onSave={c => { store.addCustomer(c); setAdding(false); notify(`${c.name} añadido a clientes`); }} />}
    </div>
  );
}

function NewCustomer({ existing, onClose, onSave }: { existing: Customer[]; onClose: () => void; onSave: (c: Customer) => void }) {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [city, setCity] = useState('Madrid');
  const [err, setErr] = useState<{ name?: string; email?: string }>({});
  const submit = (e: FormEvent) => {
    e.preventDefault();
    const x: typeof err = {};
    if (name.trim().split(/\s+/).length < 2) x.name = 'Escribe nombre y apellido.';
    if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(email.trim())) x.email = 'Revisa el email (ej.: nombre@dominio.es).';
    else if (existing.some(c => c.email === email.trim().toLowerCase())) x.email = 'Ya existe un cliente con este email.';
    setErr(x);
    if (Object.keys(x).length) return;
    onSave({ id: `c-${Date.now()}`, name: name.trim(), email: email.trim().toLowerCase(), city, since: 0 });
  };
  return (
    <Modal title="Añadir cliente" onClose={onClose}>
      <form onSubmit={submit} noValidate className="space-y-4">
        <Field label="Nombre completo" error={err.name}><input value={name} onChange={e => setName(e.target.value)} placeholder="Ej.: Laura Prieto" className={inputCls} autoFocus /></Field>
        <Field label="Email" error={err.email}><input type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="laura.prieto@gmail.com" className={inputCls} /></Field>
        <Field label="Ciudad">
          <select value={city} onChange={e => setCity(e.target.value)} className={inputCls}>{CITIES.map(c => <option key={c}>{c}</option>)}</select>
        </Field>
        <div className="flex justify-end gap-2 pt-1">
          <Button variant="ghost" onClick={onClose}>Cancelar</Button>
          <Button type="submit">Guardar cliente</Button>
        </div>
      </form>
    </Modal>
  );
}

import { useMemo, useState } from 'react';
import { clsx } from 'clsx';
import { Check, Mail, MapPin, Trash2, Truck, Undo2 } from 'lucide-react';
import { CHANNELS, STATUS, type Order, type Status } from '../data/catalog';
import type { Store } from '../lib/store';
import { customerStats } from '../lib/metrics';
import { money, num, time, weekDate } from '../lib/format';
import { Avatar, Button, Drawer, ProductThumb, StatusBadge } from './ui';

const FLOW: Status[] = ['pendiente', 'preparando', 'enviado', 'entregado'];
const NEXT: Partial<Record<Status, { to: Status; label: string }>> = {
  pendiente: { to: 'preparando', label: 'Confirmar pago' },
  preparando: { to: 'enviado', label: 'Marcar como enviado' },
  enviado: { to: 'entregado', label: 'Marcar como entregado' },
};

export default function OrderDrawer({ order, store, notify, onClose }: { order: Order; store: Store; notify: (m: string) => void; onClose: () => void }) {
  const [note, setNote] = useState(order.note ?? '');
  const [confirm, setConfirm] = useState<'refund' | 'delete' | null>(null);
  const customer = store.customers.find(c => c.id === order.customerId);
  const stats = useMemo(() => customerStats(store.orders.filter(o => o.customerId === order.customerId)).get(order.customerId), [store.orders, order.customerId]);
  const products = new Map(store.products.map(p => [p.id, p]));
  const subtotal = order.items.reduce((s, i) => s + i.qty * i.price, 0);
  const step = FLOW.indexOf(order.status);
  const next = NEXT[order.status];

  const setStatus = (s: Status) => { store.updateOrder(order.id, { status: s }); notify(`${order.id}: ${STATUS[s].label.toLowerCase()}`); setConfirm(null); };

  return (
    <Drawer onClose={onClose} title={`Pedido ${order.id}`}
      subtitle={<span>{weekDate(order.ts)}, {time(order.ts)} · {CHANNELS[order.channel].label}</span>}
      footer={confirm ? (
        <>
          <span className="mr-auto text-sm text-[#3D4552]">{confirm === 'refund' ? `¿Reembolsar ${money(order.total)}?` : '¿Eliminar este pedido?'}</span>
          <Button variant="ghost" onClick={() => setConfirm(null)}>Cancelar</Button>
          <Button variant="danger" className="bg-[#FBE7EA]" onClick={() => {
            if (confirm === 'refund') setStatus('reembolsado');
            else { store.deleteOrder(order.id); notify(`Pedido ${order.id} eliminado`); onClose(); }
          }}>{confirm === 'refund' ? 'Sí, reembolsar' : 'Sí, eliminar'}</Button>
        </>
      ) : (
        <>
          {next && <Button onClick={() => setStatus(next.to)}>{next.to === 'enviado' ? <Truck size={16} /> : <Check size={16} />}{next.label}</Button>}
          {order.status !== 'reembolsado' && order.status !== 'pendiente' && <Button variant="danger" onClick={() => setConfirm('refund')}><Undo2 size={16} />Reembolsar</Button>}
          {order.status === 'reembolsado' && <Button variant="soft" onClick={() => setStatus('entregado')}>Anular reembolso</Button>}
          {order.manual && <Button variant="danger" className="ml-auto" onClick={() => setConfirm('delete')}><Trash2 size={16} />Eliminar</Button>}
        </>
      )}>
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <StatusBadge status={order.status} />
          <span className="num display text-2xl font-semibold">{money(order.total)}</span>
        </div>

        {order.status !== 'reembolsado' && (
          <ol className="grid grid-cols-4 gap-1.5" aria-label="Progreso del pedido">
            {FLOW.map((s, i) => (
              <li key={s}>
                <div className={clsx('h-1.5 rounded-full transition-colors duration-300', i <= step ? 'bg-[#2E7D61]' : 'bg-[#E6E9EE]')} />
                <div className={clsx('mt-1.5 text-[11px]', i <= step ? 'font-medium text-[#1F5E47]' : 'text-[#8A93A1]')}>{i === 0 ? 'Pagado' : STATUS[s].label}</div>
              </li>
            ))}
          </ol>
        )}

        {customer && (
          <section className="rounded-xl border border-[#E6E9EE] p-4">
            <div className="flex items-center gap-3">
              <Avatar c={customer} size={44} />
              <div className="min-w-0">
                <div className="truncate font-semibold">{customer.name}</div>
                <div className="num text-xs text-[#5B6472]">{num(stats?.count ?? 0)} pedidos · {money(stats?.spent ?? 0, 0)} en total</div>
              </div>
            </div>
            <div className="mt-3 space-y-1.5 text-sm text-[#3D4552]">
              <div className="flex items-center gap-2"><Mail size={15} className="text-[#8A93A1]" /><span className="truncate">{customer.email}</span></div>
              <div className="flex items-center gap-2"><MapPin size={15} className="text-[#8A93A1]" />{customer.city}</div>
            </div>
          </section>
        )}

        <section>
          <h3 className="display mb-3 text-[15px] font-semibold">Artículos</h3>
          <ul className="space-y-3">
            {order.items.map(it => {
              const p = products.get(it.productId);
              return (
                <li key={it.productId} className="flex items-center gap-3">
                  <ProductThumb image={p?.image} category={p?.category ?? 'Café'} name={it.name} size={44} />
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-sm font-medium">{it.name}</div>
                    <div className="num text-xs text-[#5B6472]">{it.qty} × {money(it.price)}</div>
                  </div>
                  <span className="num text-sm font-medium">{money(it.qty * it.price)}</span>
                </li>
              );
            })}
          </ul>
          <dl className="num mt-4 space-y-1.5 border-t border-[#E6E9EE] pt-3 text-sm">
            <div className="flex justify-between text-[#5B6472]"><dt>Subtotal</dt><dd>{money(subtotal)}</dd></div>
            {order.discount > 0 && <div className="flex justify-between text-[#1F5E47]"><dt>Descuento newsletter</dt><dd>{money(-order.discount)}</dd></div>}
            <div className="flex justify-between text-[#5B6472]"><dt>Envío</dt><dd>{order.shipping ? money(order.shipping) : 'Gratis'}</dd></div>
            <div className="flex justify-between pt-1 font-semibold"><dt>Total</dt><dd>{money(order.total)}</dd></div>
          </dl>
        </section>

        <section>
          <label htmlFor="nota" className="display mb-2 block text-[15px] font-semibold">Nota interna</label>
          <textarea id="nota" value={note} onChange={e => setNote(e.target.value)} rows={3} maxLength={400}
            placeholder="Ej.: el cliente pide molienda para cafetera italiana"
            className="w-full resize-none rounded-lg border border-[#D4D9E1] px-3 py-2 text-sm placeholder:text-[#8A93A1] focus:border-[#151A23]" />
          <div className="mt-2 flex items-center justify-between">
            <span className="text-xs text-[#8A93A1]">{order.note ? 'Nota guardada · solo la ve tu equipo' : 'Solo la ve tu equipo'}</span>
            <Button variant="soft" disabled={note.trim() === (order.note ?? '')} onClick={() => { store.updateOrder(order.id, { note: note.trim() }); notify('Nota guardada'); }}>Guardar nota</Button>
          </div>
        </section>
      </div>
    </Drawer>
  );
}

import { useMemo, useState, type FormEvent } from 'react';
import { Plus, Trash2 } from 'lucide-react';
import { CHANNELS, type Channel, type Status } from '../data/catalog';
import type { Store } from '../lib/store';
import { money } from '../lib/format';
import { Button, Field, Modal, inputCls } from './ui';

type Line = { productId: string; qty: number };

export default function OrderForm({ store, onClose, onCreated }: { store: Store; onClose: () => void; onCreated: (id: string) => void }) {
  const [customerId, setCustomerId] = useState('');
  const [channel, setChannel] = useState<Channel>('web');
  const [status, setStatus] = useState<Status>('preparando');
  const [lines, setLines] = useState<Line[]>([{ productId: '', qty: 1 }]);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const sorted = useMemo(() => [...store.customers].sort((a, b) => a.name.localeCompare(b.name, 'es')), [store.customers]);
  const products = new Map(store.products.map(p => [p.id, p]));
  const subtotal = lines.reduce((s, l) => s + (products.get(l.productId)?.price ?? 0) * l.qty, 0);
  const shipping = subtotal > 0 && subtotal < 40 ? 4.9 : 0;

  const setLine = (i: number, patch: Partial<Line>) => setLines(ls => ls.map((l, k) => (k === i ? { ...l, ...patch } : l)));

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const err: Record<string, string> = {};
    if (!customerId) err.customer = 'Elige el cliente del pedido.';
    lines.forEach((l, i) => {
      const p = products.get(l.productId);
      if (!p) err[`l${i}`] = 'Elige un producto.';
      else if (!Number.isInteger(l.qty) || l.qty < 1 || l.qty > 50) err[`l${i}`] = 'La cantidad debe estar entre 1 y 50.';
      else if (p.category !== 'Suscripciones' && l.qty > p.stock) err[`l${i}`] = `Solo quedan ${p.stock} unidades en stock.`;
    });
    if (new Set(lines.map(l => l.productId)).size !== lines.length) err.lines = 'Hay productos repetidos: suma las cantidades en una sola línea.';
    setErrors(err);
    if (Object.keys(err).length) return;

    const maxId = Math.max(...store.orders.map(o => Number(o.id.replace('PU-', ''))));
    const id = `PU-${maxId + 1}`;
    const items = lines.map(l => { const p = products.get(l.productId)!; return { productId: p.id, name: p.name, qty: l.qty, price: p.price }; });
    store.addOrder({ id, ts: Date.now(), customerId, items, shipping, discount: 0, total: Math.round((subtotal + shipping) * 100) / 100, channel, status, manual: true });
    for (const l of lines) {
      const p = products.get(l.productId)!;
      if (p.category !== 'Suscripciones') store.saveProduct({ ...p, stock: p.stock - l.qty });
    }
    onCreated(id);
  };

  return (
    <Modal title="Registrar pedido" onClose={onClose}>
      <form onSubmit={submit} noValidate className="space-y-4">
        <Field label="Cliente" error={errors.customer}>
          <select value={customerId} onChange={e => setCustomerId(e.target.value)} className={inputCls}>
            <option value="">Selecciona un cliente…</option>
            {sorted.map(c => <option key={c.id} value={c.id}>{c.name} · {c.city}</option>)}
          </select>
        </Field>
        <div className="space-y-2">
          <span className="block text-[13px] font-medium text-[#3D4552]">Productos</span>
          {lines.map((l, i) => (
            <div key={i}>
              <div className="flex gap-2">
                <select value={l.productId} onChange={e => setLine(i, { productId: e.target.value })} aria-label={`Producto ${i + 1}`} className={`${inputCls} min-w-0 flex-1`}>
                  <option value="">Elige producto…</option>
                  {store.products.map(p => <option key={p.id} value={p.id}>{p.name} · {money(p.price)}</option>)}
                </select>
                <input type="number" min={1} max={50} value={l.qty} onChange={e => setLine(i, { qty: Number(e.target.value) })} aria-label="Cantidad" className={`${inputCls} !w-16 shrink-0 text-center`} />
                {lines.length > 1 && <button type="button" onClick={() => setLines(ls => ls.filter((_, k) => k !== i))} aria-label="Quitar línea" className="rounded-lg px-2 text-[#5B6472] hover:bg-[#FBE7EA] hover:text-[#A3243A]"><Trash2 size={16} /></button>}
              </div>
              {errors[`l${i}`] && <span className="mt-1 block text-xs text-[#A3243A]">{errors[`l${i}`]}</span>}
            </div>
          ))}
          {errors.lines && <span className="block text-xs text-[#A3243A]">{errors.lines}</span>}
          {lines.length < 4 && (
            <button type="button" onClick={() => setLines(ls => [...ls, { productId: '', qty: 1 }])} className="inline-flex items-center gap-1 rounded-lg px-1 py-1 text-sm font-medium text-[#C0283F] hover:underline">
              <Plus size={15} />Añadir producto
            </button>
          )}
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Canal">
            <select value={channel} onChange={e => setChannel(e.target.value as Channel)} className={inputCls}>
              {(Object.keys(CHANNELS) as Channel[]).map(c => <option key={c} value={c}>{CHANNELS[c].label}</option>)}
            </select>
          </Field>
          <Field label="Pago">
            <select value={status} onChange={e => setStatus(e.target.value as Status)} className={inputCls}>
              <option value="preparando">Cobrado</option>
              <option value="pendiente">Pendiente de pago</option>
            </select>
          </Field>
        </div>
        <div className="num space-y-1 rounded-xl bg-[#F4F6F8] px-4 py-3 text-sm">
          <div className="flex justify-between text-[#5B6472]"><span>Subtotal</span><span>{money(subtotal)}</span></div>
          <div className="flex justify-between text-[#5B6472]"><span>Envío {subtotal >= 40 && '(gratis desde 40 €)'}</span><span>{money(shipping)}</span></div>
          <div className="flex justify-between pt-1 font-semibold"><span>Total</span><span>{money(subtotal + shipping)}</span></div>
        </div>
        <div className="flex justify-end gap-2 pt-1">
          <Button variant="ghost" onClick={onClose}>Cancelar</Button>
          <Button type="submit">Guardar pedido</Button>
        </div>
      </form>
    </Modal>
  );
}

import { useMemo, useState, type KeyboardEvent } from 'react';
import { ChevronLeft, ChevronRight, Download, Plus, Search, SearchX } from 'lucide-react';
import { CHANNELS, STATUS, type Channel, type Order, type Status } from '../data/catalog';
import type { ViewProps } from '../lib/store';
import { inPeriod } from '../lib/metrics';
import { money, relative, shortDate, time } from '../lib/format';
import { Button, Card, Chips, Empty, StatusBadge, inputCls } from './ui';
import OrderForm from './OrderForm';

type Sort = 'recientes' | 'antiguos' | 'mayor' | 'menor';
const PAGE = 12;

export default function Orders({ store, period, openOrder, notify }: ViewProps) {
  const [q, setQ] = useState('');
  const [status, setStatus] = useState<Status | 'todos'>('todos');
  const [channel, setChannel] = useState<Channel | 'todos'>('todos');
  const [sort, setSort] = useState<Sort>('recientes');
  const [page, setPage] = useState(0);
  const [creating, setCreating] = useState(false);

  const customers = useMemo(() => new Map(store.customers.map(c => [c.id, c])), [store.customers]);
  const base = useMemo(() => inPeriod(store.orders, period), [store.orders, period]);

  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    const list = base.filter(o => {
      if (status !== 'todos' && o.status !== status) return false;
      if (channel !== 'todos' && o.channel !== channel) return false;
      if (!term) return true;
      const c = customers.get(o.customerId);
      return o.id.toLowerCase().includes(term) || !!c?.name.toLowerCase().includes(term) || !!c?.city.toLowerCase().includes(term)
        || o.items.some(i => i.name.toLowerCase().includes(term));
    });
    const by: Record<Sort, (a: Order, b: Order) => number> = {
      recientes: (a, b) => b.ts - a.ts, antiguos: (a, b) => a.ts - b.ts, mayor: (a, b) => b.total - a.total, menor: (a, b) => a.total - b.total,
    };
    return list.sort(by[sort]);
  }, [base, q, status, channel, sort, customers]);

  const pages = Math.max(1, Math.ceil(filtered.length / PAGE));
  const cur = Math.min(page, pages - 1);
  const rows = filtered.slice(cur * PAGE, cur * PAGE + PAGE);
  const counts = (s: Status) => base.filter(o => o.status === s).length;
  const reset = (fn: () => void) => { fn(); setPage(0); };

  const exportCsv = () => {
    const head = 'Pedido;Fecha;Cliente;Canal;Estado;Artículos;Total\n';
    const body = filtered.map(o => [o.id, new Date(o.ts).toLocaleString('es-ES'), customers.get(o.customerId)?.name ?? '', CHANNELS[o.channel].label,
      STATUS[o.status].label, o.items.reduce((s, i) => s + i.qty, 0), o.total.toFixed(2).replace('.', ',')].join(';')).join('\n');
    const url = URL.createObjectURL(new Blob(['﻿' + head + body], { type: 'text/csv;charset=utf-8' }));
    const a = document.createElement('a');
    a.href = url; a.download = `pedidos-${period}-dias.csv`; a.click();
    URL.revokeObjectURL(url);
    notify(`${filtered.length} pedidos exportados a CSV`);
  };

  const onKey = (e: KeyboardEvent, id: string) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); openOrder(id); } };

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-3 md:flex-row md:items-center">
        <div className="relative flex-1">
          <Search size={17} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[#8A93A1]" />
          <input value={q} onChange={e => reset(() => setQ(e.target.value))} placeholder="Buscar por pedido, cliente, ciudad o producto"
            aria-label="Buscar pedidos" className={`${inputCls} pl-9`} />
        </div>
        <div className="flex gap-2">
          <select value={channel} onChange={e => reset(() => setChannel(e.target.value as Channel | 'todos'))} aria-label="Canal" className={`${inputCls} w-auto flex-1 md:w-44`}>
            <option value="todos">Todos los canales</option>
            {(Object.keys(CHANNELS) as Channel[]).map(c => <option key={c} value={c}>{CHANNELS[c].label}</option>)}
          </select>
          <select value={sort} onChange={e => setSort(e.target.value as Sort)} aria-label="Ordenar" className={`${inputCls} w-auto flex-1 md:w-40`}>
            <option value="recientes">Más recientes</option>
            <option value="antiguos">Más antiguos</option>
            <option value="mayor">Mayor importe</option>
            <option value="menor">Menor importe</option>
          </select>
        </div>
        <div className="flex gap-2">
          <Button variant="soft" onClick={exportCsv} className="h-10 flex-1"><Download size={16} />Exportar</Button>
          <Button onClick={() => setCreating(true)} className="h-10 flex-1"><Plus size={16} />Registrar pedido</Button>
        </div>
      </div>

      <Chips value={status} onChange={v => reset(() => setStatus(v))} options={[
        { id: 'todos', label: 'Todos', count: base.length },
        ...(Object.keys(STATUS) as Status[]).map(s => ({ id: s, label: STATUS[s].label, count: counts(s) })),
      ]} />

      <Card className="overflow-hidden">
        {rows.length === 0 ? (
          <Empty icon={<SearchX size={22} />} title="No hay pedidos con estos filtros" text="Prueba con otro término, cambia el estado o amplía el periodo."
            action={<Button variant="soft" onClick={() => reset(() => { setQ(''); setStatus('todos'); setChannel('todos'); })}>Quitar filtros</Button>} />
        ) : (
          <>
            <table className="hidden w-full text-sm md:table">
              <thead>
                <tr className="border-b border-[#E6E9EE] bg-[#F7F8FA] text-left text-xs font-medium text-[#5B6472]">
                  <th className="px-5 py-3 font-medium">Pedido</th><th className="px-3 py-3 font-medium">Cliente</th>
                  <th className="px-3 py-3 font-medium">Fecha</th><th className="px-3 py-3 font-medium">Canal</th>
                  <th className="px-3 py-3 font-medium">Estado</th><th className="px-5 py-3 text-right font-medium">Total</th>
                </tr>
              </thead>
              <tbody>
                {rows.map(o => {
                  const c = customers.get(o.customerId);
                  return (
                    <tr key={o.id} role="button" tabIndex={0} onClick={() => openOrder(o.id)} onKeyDown={e => onKey(e, o.id)}
                      className="cursor-pointer border-b border-[#EEF0F3] last:border-0 hover:bg-[#F7F8FA]">
                      <td className="px-5 py-3 font-medium">{o.id}{o.manual && <span className="ml-2 rounded bg-[#EEF1F4] px-1.5 py-0.5 text-[11px] text-[#5B6472]">Manual</span>}</td>
                      <td className="px-3 py-3"><div className="font-medium">{c?.name}</div><div className="text-xs text-[#5B6472]">{c?.city}</div></td>
                      <td className="num px-3 py-3 text-[#3D4552]">{shortDate(o.ts)}<span className="text-[#8A93A1]"> · {time(o.ts)}</span></td>
                      <td className="px-3 py-3"><span className="inline-flex items-center gap-2 text-[#3D4552]"><span className="h-2 w-2 rounded-full" style={{ background: CHANNELS[o.channel].color }} />{CHANNELS[o.channel].label}</span></td>
                      <td className="px-3 py-3"><StatusBadge status={o.status} /></td>
                      <td className="num px-5 py-3 text-right font-semibold">{money(o.total)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
            <ul className="divide-y divide-[#EEF0F3] md:hidden">
              {rows.map(o => (
                <li key={o.id}>
                  <button onClick={() => openOrder(o.id)} className="flex w-full items-start gap-3 px-4 py-3.5 text-left">
                    <div className="min-w-0 flex-1">
                      <div className="truncate text-sm font-medium">{customers.get(o.customerId)?.name}</div>
                      <div className="mt-0.5 text-xs text-[#5B6472]">{o.id} · {relative(o.ts)}</div>
                      <div className="mt-2"><StatusBadge status={o.status} /></div>
                    </div>
                    <span className="num text-sm font-semibold">{money(o.total)}</span>
                  </button>
                </li>
              ))}
            </ul>
          </>
        )}
        <div className="flex items-center justify-between border-t border-[#E6E9EE] px-5 py-3 text-sm text-[#5B6472]">
          <span className="num">{filtered.length ? `${cur * PAGE + 1}–${Math.min(filtered.length, (cur + 1) * PAGE)} de ${filtered.length}` : '0 pedidos'}</span>
          <div className="flex gap-1">
            <button disabled={cur === 0} onClick={() => setPage(cur - 1)} aria-label="Página anterior" className="rounded-lg p-1.5 hover:bg-[#EEF1F4] disabled:opacity-30"><ChevronLeft size={18} /></button>
            <button disabled={cur >= pages - 1} onClick={() => setPage(cur + 1)} aria-label="Página siguiente" className="rounded-lg p-1.5 hover:bg-[#EEF1F4] disabled:opacity-30"><ChevronRight size={18} /></button>
          </div>
        </div>
      </Card>

      {creating && <OrderForm store={store} onClose={() => setCreating(false)} onCreated={id => { setCreating(false); notify(`Pedido ${id} registrado`); openOrder(id); }} />}
    </div>
  );
}

import { useMemo } from 'react';
import { ChevronRight, MousePointerClick, Receipt, ShoppingBag, Wallet } from 'lucide-react';
import { CHANNELS } from '../data/catalog';
import type { ViewProps } from '../lib/store';
import { channelShare, delta, periodStats, productRanking } from '../lib/metrics';
import { money, num, pct, relative } from '../lib/format';
import { Card, CardHead, Delta, ProductThumb, StatusBadge } from './ui';
import { Donut, RevenueChart, Sparkline } from './charts';

export default function Overview({ store, period, openOrder, goTo }: ViewProps & { goTo: () => void }) {
  const now = useMemo(() => periodStats(store.orders, store.sessions, period), [store.orders, store.sessions, period]);
  const before = useMemo(() => periodStats(store.orders, store.sessions, period, period), [store.orders, store.sessions, period]);
  const ranking = useMemo(() => productRanking(now.list).slice(0, 5), [now.list]);
  const channels = useMemo(() => channelShare(now.list), [now.list]);
  const customers = useMemo(() => new Map(store.customers.map(c => [c.id, c])), [store.customers]);

  const done = now.daily.slice(0, -1); // hoy aún está en curso
  const kpis = [
    { label: 'Ingresos', icon: Wallet, value: money(now.revenue, 0), d: delta(now.revenue, before.revenue), spark: done.map(d => d.revenue) },
    { label: 'Pedidos', icon: ShoppingBag, value: num(now.orders), d: delta(now.orders, before.orders), spark: done.map(d => d.orders) },
    { label: 'Ticket medio', icon: Receipt, value: money(now.aov), d: delta(now.aov, before.aov), spark: done.map(d => (d.orders ? d.revenue / d.orders : 0)) },
    { label: 'Conversión', icon: MousePointerClick, value: pct(now.conversion, 2), d: delta(now.conversion, before.conversion), spark: done.map(d => (d.sessions ? d.orders / d.sessions : 0)) },
  ];
  const top = ranking[0]?.revenue || 1;
  const productsById = new Map(store.products.map(p => [p.id, p]));

  return (
    <div className="space-y-5">
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {kpis.map(k => (
          <Card key={k.label} className="px-5 py-4">
            <div className="flex items-center justify-between gap-2">
              <span className="flex items-center gap-2 text-sm text-[#5B6472]"><k.icon size={16} />{k.label}</span>
              <span title={`Frente a los ${period} días anteriores`}><Delta value={k.d} /></span>
            </div>
            <div className="num display mt-2.5 text-[28px] font-semibold leading-none">{k.value}</div>
            <div className="mt-3"><Sparkline values={k.spark} color={k.d >= 0 ? '#2E7D61' : '#C0283F'} /></div>
          </Card>
        ))}
      </div>

      <div className="grid grid-cols-1 gap-5 lg:grid-cols-3">
        <Card className="lg:col-span-2">
          <CardHead title="Ingresos diarios" hint={`${money(now.revenue, 0)} en ${period} días · ${num(now.refunds)} reembolsos excluidos`} action={
            <div className="hidden items-center gap-4 text-xs text-[#5B6472] sm:flex">
              <span className="flex items-center gap-1.5"><span className="h-0.5 w-4 rounded bg-[#C0283F]" />Este periodo</span>
              <span className="flex items-center gap-1.5"><span className="w-4 border-t-2 border-dashed border-[#A7AFBB]" />Anterior</span>
            </div>
          } />
