import { useMemo, useState, type FormEvent } from 'react';
import { clsx } from 'clsx';
import { PackageSearch, Pencil, Plus, Search, Trash2, TriangleAlert } from 'lucide-react';
import type { Category, Product } from '../data/catalog';
import type { Store, ViewProps } from '../lib/store';
import { inPeriod, productRanking } from '../lib/metrics';
import { money, num } from '../lib/format';
import { Button, Card, Chips, Empty, Field, Modal, ProductThumb, inputCls } from './ui';

type Cat = Category | 'todas';
type Sort = 'ingresos' | 'unidades' | 'stock' | 'nombre';

export default function Products({ store, period, notify }: ViewProps) {
  const [cat, setCat] = useState<Cat>('todas');
  const [q, setQ] = useState('');
  const [sort, setSort] = useState<Sort>('ingresos');
  const [editing, setEditing] = useState<Product | 'new' | null>(null);

  const sales = useMemo(() => new Map(productRanking(inPeriod(store.orders, period)).map(r => [r.id, r])), [store.orders, period]);
  const rows = useMemo(() => {
    const term = q.trim().toLowerCase();
    const list = store.products
      .filter(p => (cat === 'todas' || p.category === cat) && (!term || p.name.toLowerCase().includes(term) || p.sku.toLowerCase().includes(term)))
      .map(p => ({ p, units: sales.get(p.id)?.units ?? 0, revenue: sales.get(p.id)?.revenue ?? 0 }));
    const by: Record<Sort, (a: typeof list[0], b: typeof list[0]) => number> = {
      ingresos: (a, b) => b.revenue - a.revenue, unidades: (a, b) => b.units - a.units,
      stock: (a, b) => a.p.stock - b.p.stock, nombre: (a, b) => a.p.name.localeCompare(b.p.name, 'es'),
    };
    return list.sort(by[sort]);
  }, [store.products, sales, cat, q, sort]);

  const top = Math.max(1, ...rows.map(r => r.revenue));
  const totalRevenue = rows.reduce((s, r) => s + r.revenue, 0);
  const totalUnits = rows.reduce((s, r) => s + r.units, 0);
  const lowStock = (p: Product) => p.category !== 'Suscripciones' && p.stock < 20;
  const lowCount = store.products.filter(lowStock).length;
  const count = (c: Category) => store.products.filter(p => p.category === c).length;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-3">
        <Card className="px-5 py-4"><div className="text-sm text-[#5B6472]">Ingresos por producto</div><div className="num display mt-1.5 text-2xl font-semibold">{money(totalRevenue, 0)}</div></Card>
        <Card className="px-5 py-4"><div className="text-sm text-[#5B6472]">Unidades vendidas</div><div className="num display mt-1.5 text-2xl font-semibold">{num(totalUnits)}</div></Card>
        <Card className={clsx('px-5 py-4', lowCount && 'border-[#F1D9A6] bg-[#FFFBF2]')}>
          <div className="flex items-center gap-1.5 text-sm text-[#5B6472]">{lowCount > 0 && <TriangleAlert size={15} className="text-[#C98A12]" />}Stock bajo (menos de 20 u.)</div>
          <div className="num display mt-1.5 text-2xl font-semibold">{lowCount} {lowCount === 1 ? 'producto' : 'productos'}</div>
        </Card>
      </div>

      <div className="flex flex-col gap-3 md:flex-row md:items-center">
        <div className="relative flex-1">
          <Search size={17} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[#8A93A1]" />
          <input value={q} onChange={e => setQ(e.target.value)} placeholder="Buscar por nombre o SKU" aria-label="Buscar productos" className={`${inputCls} pl-9`} />
        </div>
        <div className="flex gap-2">
          <select value={sort} onChange={e => setSort(e.target.value as Sort)} aria-label="Ordenar productos" className={`${inputCls} w-auto flex-1 md:w-48`}>
            <option value="ingresos">Más ingresos</option>
            <option value="unidades">Más unidades</option>
            <option value="stock">Menos stock</option>
            <option value="nombre">Nombre (A–Z)</option>
          </select>
          <Button onClick={() => setEditing('new')} className="h-10"><Plus size={16} />Nuevo producto</Button>
        </div>
      </div>

      <Chips value={cat} onChange={setCat} options={[
        { id: 'todas', label: 'Todas', count: store.products.length },
        ...(['Café', 'Accesorios', 'Suscripciones'] as Category[]).map(c => ({ id: c, label: c, count: count(c) })),
      ]} />

      <Card className="overflow-hidden">
        {rows.length === 0 ? (
          <Empty icon={<PackageSearch size={22} />} title="Ningún producto coincide" text="Revisa el nombre o el SKU, o crea el producto si aún no está en el catálogo."
            action={<Button onClick={() => setEditing('new')}><Plus size={16} />Nuevo producto</Button>} />
        ) : (
          <ul className="divide-y divide-[#EEF0F3]">
            <li className="hidden grid-cols-[minmax(0,2.2fr)_1fr_0.8fr_1.6fr_0.9fr_40px] gap-4 bg-[#F7F8FA] px-5 py-3 text-xs font-medium text-[#5B6472] md:grid">
              <span>Producto</span><span className="text-right">Precio</span><span className="text-right">Unidades</span><span>Ingresos ({period} días)</span><span className="text-right">Stock</span><span />
            </li>
            {rows.map(({ p, units, revenue }) => (
              <li key={p.id} className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-4 gap-y-2 px-5 py-3.5 md:grid-cols-[minmax(0,2.2fr)_1fr_0.8fr_1.6fr_0.9fr_40px]">
                <div className="flex min-w-0 items-center gap-3">
                  <ProductThumb image={p.image} category={p.category} name={p.name} size={44} />
                  <div className="min-w-0">
                    <div className="truncate text-sm font-medium">{p.name}</div>
                    <div className="text-xs text-[#5B6472]">{p.sku} · {p.category}</div>
                  </div>
                </div>
                <span className="num hidden text-right text-sm md:block">{money(p.price)}</span>
                <span className="num hidden text-right text-sm md:block">{num(units)}</span>
                <div className="col-span-2 flex items-center gap-3 md:col-span-1">
                  <div className="h-2 flex-1 overflow-hidden rounded-full bg-[#EEF1F4]">
                    <div className="bar-grow h-full rounded-full bg-[#C0283F]" style={{ width: `${(revenue / top) * 100}%` }} />
                  </div>
                  <span className="num w-20 text-right text-sm font-semibold">{money(revenue, 0)}</span>
                </div>
                <span className="num hidden text-right text-sm md:block">
                  {p.category === 'Suscripciones' ? <span className="text-[#8A93A1]">—</span>
                    : <span className={clsx(lowStock(p) && 'rounded-md bg-[#FBF1DC] px-1.5 py-0.5 font-semibold text-[#7A5208]')}>{num(p.stock)}</span>}
                </span>
                <button onClick={() => setEditing(p)} aria-label={`Editar ${p.name}`} className="row-start-1 col-start-2 justify-self-end rounded-lg p-2 text-[#5B6472] hover:bg-[#EEF1F4] hover:text-[#151A23] md:col-start-auto md:row-start-auto">
                  <Pencil size={16} />
                </button>
              </li>
            ))}
          </ul>
        )}
      </Card>

      {editing && (
        <ProductForm product={editing === 'new' ? null : editing} store={store} onClose={() => setEditing(null)}
          onDone={msg => { setEditing(null); notify(msg); }} />
      )}
    </div>
  );
}

type Draft = { name: string; sku: string; category: Category; price: string; stock: string };

function ProductForm({ product, store, onClose, onDone }: {
  product: Product | null; store: Store; onClose: () => void; onDone: (msg: string) => void;
}) {
  const [d, setD] = useState<Draft>(product
    ? { name: product.name, sku: product.sku, category: product.category, price: String(product.price).replace('.', ','), stock: String(product.stock) }
    : { name: '', sku: '', category: 'Café', price: '', stock: '' });
  const [errors, setErrors] = useState<Partial<Record<keyof Draft, string>>>({});
  const [confirmDelete, setConfirmDelete] = useState(false);
  const set = (k: keyof Draft) => (e: { target: { value: string } }) => setD(x => ({ ...x, [k]: e.target.value }));

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const price = Number(d.price.replace(',', '.'));
    const stock = Number(d.stock);
    const err: typeof errors = {};
    if (d.name.trim().length < 3) err.name = 'Escribe un nombre de al menos 3 letras.';
    if (!/^[A-Z0-9-]{4,16}$/i.test(d.sku.trim())) err.sku = 'Usa de 4 a 16 letras, números o guiones (ej.: CF-KEN-250).';
    else if (store.products.some(p => p.sku.toLowerCase() === d.sku.trim().toLowerCase() && p.id !== product?.id)) err.sku = 'Ya hay un producto con este SKU.';
    if (!(price > 0) || price > 5000) err.price = 'Indica un precio entre 0,01 y 5.000 €.';
    if (!Number.isInteger(stock) || stock < 0 || d.stock.trim() === '') err.stock = 'El stock debe ser un número entero (0 o más).';
    setErrors(err);
    if (Object.keys(err).length) return;
    store.saveProduct({
      id: product?.id ?? `p${Date.now()}`, weight: product?.weight ?? 1, image: product?.image,
      name: d.name.trim(), sku: d.sku.trim().toUpperCase(), category: d.category, price: Math.round(price * 100) / 100, stock,
    });
    onDone(product ? 'Cambios guardados' : `«${d.name.trim()}» añadido al catálogo`);
  };

  return (
    <Modal title={product ? 'Editar producto' : 'Nuevo producto'} onClose={onClose}>
      <form onSubmit={submit} noValidate className="space-y-4">
        <Field label="Nombre" error={errors.name}>
          <input value={d.name} onChange={set('name')} placeholder="Ej.: Kenia Nyeri 250 g" className={inputCls} autoFocus />
        </Field>
        <div className="grid grid-cols-2 gap-3">
          <Field label="SKU" error={errors.sku}><input value={d.sku} onChange={set('sku')} placeholder="CF-KEN-250" className={inputCls} /></Field>
          <Field label="Categoría">
            <select value={d.category} onChange={set('category')} className={inputCls}>
              <option>Café</option><option>Accesorios</option><option>Suscripciones</option>
            </select>
          </Field>
          <Field label="Precio (€)" error={errors.price}><input inputMode="decimal" value={d.price} onChange={set('price')} placeholder="12,90" className={inputCls} /></Field>
          <Field label="Stock (unidades)" error={errors.stock}><input inputMode="numeric" value={d.stock} onChange={set('stock')} placeholder="100" className={inputCls} /></Field>
        </div>
        {product && <p className="text-xs text-[#5B6472]">Cambiar el precio no modifica los pedidos ya realizados.</p>}
        <div className="flex items-center gap-2 pt-2">
          {product && (confirmDelete ? (
            <Button variant="danger" className="bg-[#FBE7EA]" onClick={() => { store.deleteProduct(product.id); onDone(`«${product.name}» eliminado`); }}>Confirmar borrado</Button>
          ) : (
            <Button variant="danger" onClick={() => setConfirmDelete(true)}><Trash2 size={16} />Eliminar</Button>
          ))}
          <Button variant="ghost" className="ml-auto" onClick={onClose}>Cancelar</Button>
          <Button type="submit">{product ? 'Guardar cambios' : 'Crear producto'}</Button>
        </div>
      </form>
    </Modal>
  );
}

import { useEffect, useRef, useState, type MouseEvent } from 'react';
import type { DayPoint } from '../lib/metrics';
import { money, moneyShort, num, shortDate, weekDate } from '../lib/format';

function useWidth<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [w, setW] = useState(600);
  useEffect(() => {
    if (!ref.current) return;
    const ro = new ResizeObserver(([e]) => setW(Math.max(240, e.contentRect.width)));
    ro.observe(ref.current);
    return () => ro.disconnect();
  }, []);
  return [ref, w] as const;
}

/** Curva suave (Catmull-Rom → Bézier) limitada al área del gráfico. */
function smooth(pts: Array<[number, number]>, maxY: number) {
  if (pts.length < 2) return '';
  let d = `M${pts[0][0]},${pts[0][1]}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i - 1] ?? pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] ?? p2;
    const t = 0.15;
    const c1y = Math.min(maxY, p1[1] + (p2[1] - p0[1]) * t), c2y = Math.min(maxY, p2[1] - (p3[1] - p1[1]) * t);
    d += ` C${p1[0] + (p2[0] - p0[0]) * t},${c1y} ${p2[0] - (p3[0] - p1[0]) * t},${c2y} ${p2[0]},${p2[1]}`;
  }
  return d;
}

function niceMax(v: number) {
  const step = Math.pow(10, Math.floor(Math.log10(v || 1)));
  for (const m of [1, 1.5, 2, 2.5, 3, 4, 5, 6, 8, 10]) if (m * step >= v) return m * step;
  return 10 * step;
}

export function RevenueChart({ data, prev }: { data: DayPoint[]; prev: DayPoint[] }) {
  const [ref, width] = useWidth<HTMLDivElement>();
  const [hover, setHover] = useState<number | null>(null);
  const H = 294, L = 52, R = 12, T = 12, B = 28;
  const iw = width - L - R, ih = H - T - B;
  const max = niceMax(Math.max(...data.map(d => d.revenue), ...prev.map(d => d.revenue)) * 1.08);
  const x = (i: number) => L + (data.length === 1 ? iw / 2 : (i / (data.length - 1)) * iw);
  const y = (v: number) => T + ih - (v / max) * ih;
  const pts = data.map((d, i) => [x(i), y(d.revenue)] as [number, number]);
  const prevPts = prev.map((d, i) => [x(i), y(d.revenue)] as [number, number]);
  const line = smooth(pts.slice(0, -1), T + ih);
  const [pa, pb] = [pts[pts.length - 2], pts[pts.length - 1]];
  const area = `${line} L${pb[0]},${pb[1]} L${x(data.length - 1)},${T + ih} L${x(0)},${T + ih} Z`;
  const ticks = [0, 0.25, 0.5, 0.75, 1].map(f => f * max);
  const every = Math.ceil(data.length / Math.max(3, Math.floor(iw / 90)));

  const onMove = (e: MouseEvent<SVGSVGElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const i = Math.round(((e.clientX - rect.left - L) / iw) * (data.length - 1));
    setHover(Math.min(data.length - 1, Math.max(0, i)));
  };
  const h = hover !== null ? data[hover] : null;

  return (
    <div ref={ref} className="relative w-full select-none">
      <svg width={width} height={H} onMouseMove={onMove} onMouseLeave={() => setHover(null)} role="img" aria-label="Ingresos diarios del periodo">
        <defs>
          <linearGradient id="pulso-area" x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor="#C0283F" stopOpacity="0.22" />
            <stop offset="100%" stopColor="#C0283F" stopOpacity="0" />
          </linearGradient>
        </defs>
        {ticks.map(t => (
          <g key={t}>
            <line x1={L} x2={width - R} y1={y(t)} y2={y(t)} stroke="#E9ECF0" strokeDasharray={t ? '3 4' : undefined} />
            <text x={L - 10} y={y(t) + 4} textAnchor="end" className="num" fontSize="11" fill="#6B7380">{moneyShort(t)}</text>
          </g>
        ))}
        {data.map((d, i) => (i % every === 0 || i === data.length - 1) && (data.length - 1 - i >= every / 2 || i === data.length - 1) ? (
          <text key={d.ts} x={x(i)} y={H - 8} textAnchor={i === data.length - 1 ? 'end' : i === 0 ? 'start' : 'middle'} fontSize="11" fill="#6B7380">
            {i === data.length - 1 ? 'Hoy' : shortDate(d.ts)}
          </text>
        ) : null)}
        <path d={smooth(prevPts, T + ih)} fill="none" stroke="#A7AFBB" strokeWidth="1.5" strokeDasharray="4 4" />
        <g className="reveal" key={data.length}>
          <path d={area} fill="url(#pulso-area)" />
          <path d={line} fill="none" stroke="#C0283F" strokeWidth="2.25" strokeLinejoin="round" />
          {pa && <path d={`M${pa[0]},${pa[1]} L${pb[0]},${pb[1]}`} stroke="#C0283F" strokeWidth="2.25" strokeDasharray="3 4" strokeLinecap="round" />}
        </g>
        {h && hover !== null && (
          <g pointerEvents="none">
            <line x1={x(hover)} x2={x(hover)} y1={T} y2={T + ih} stroke="#151A23" strokeOpacity="0.25" />
            <circle cx={x(hover)} cy={y(h.revenue)} r="5" fill="#fff" stroke="#C0283F" strokeWidth="2.5" />
          </g>
        )}
      </svg>
      {h && hover !== null && (
        <div className="pointer-events-none absolute top-2 z-10 w-48 rounded-xl bg-[#151A23] px-3.5 py-3 text-white shadow-xl"
          style={{ left: Math.min(Math.max(x(hover) - 96, 0), width - 192) }}>
          <div className="text-xs text-white/60">{weekDate(h.ts)}{hover === data.length - 1 && ' · en curso'}</div>
          <div className="num display mt-0.5 text-lg font-semibold">{money(h.revenue)}</div>
          <div className="num mt-1.5 flex justify-between text-xs text-white/75"><span>{num(h.orders)} pedidos</span><span>{num(h.sessions)} visitas</span></div>
          {prev[hover] && <div className="num mt-1 text-xs text-white/50">Periodo anterior: {money(prev[hover].revenue, 0)}</div>}
        </div>
      )}
    </div>
  );
}

export function Sparkline({ values, color = '#C0283F' }: { values: number[]; color?: string }) {
  const w = 200, h = 30;
  const max = Math.max(...values), min = Math.min(...values);
  const pts = values.map((v, i) => `${(i / (values.length - 1)) * w},${h - 3 - ((v - min) / (max - min || 1)) * (h - 6)}`);
  return (
    <svg viewBox={`0 0 ${w} ${h}`} preserveAspectRatio="none" className="reveal block h-[30px] w-full" aria-hidden="true">
      <polyline points={pts.join(' ')} fill="none" stroke={color} strokeWidth="1.6" strokeLinejoin="round" strokeLinecap="round" vectorEffect="non-scaling-stroke" />
    </svg>
  );
}

export type Slice = { key: string; label: string; color: string; value: number; share: number };

export function Donut({ slices, size = 150 }: { slices: Slice[]; size?: number }) {
  const [active, setActive] = useState<string | null>(null);
  const r = size / 2 - 14, c = 2 * Math.PI * r;
  let acc = 0;
  const cur = slices.find(s => s.key === active);
  const total = slices.reduce((s, x) => s + x.value, 0);
  return (
    <div className="flex flex-col items-center gap-5">
      <div className="relative shrink-0" style={{ width: size, height: size }}>
        <svg width={size} height={size} className="-rotate-90" role="img" aria-label="Ingresos por canal">
          <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="#EEF1F4" strokeWidth="18" />
          {slices.map(s => {
            const len = s.share * c, gap = slices.length > 1 ? 3 : 0;
            const el = (
              <circle key={s.key} cx={size / 2} cy={size / 2} r={r} fill="none" stroke={s.color}
                strokeWidth={active === s.key ? 24 : 18} strokeDasharray={`${Math.max(0, len - gap)} ${c}`} strokeDashoffset={-acc}
                className="cursor-pointer transition-all duration-200" style={{ opacity: active && active !== s.key ? 0.35 : 1 }}
                onMouseEnter={() => setActive(s.key)} onMouseLeave={() => setActive(null)} />
            );
            acc += len;
            return el;
          })}
        </svg>
        <div className="pointer-events-none absolute inset-0 grid place-items-center text-center">
          <div>
            <div className="num display text-xl font-semibold text-[#151A23]">{cur ? `${Math.round(cur.share * 100)} %` : moneyShort(total)}</div>
            <div className="text-xs text-[#5B6472]">{cur ? cur.label : 'en el periodo'}</div>
          </div>
        </div>
      </div>
      <ul className="w-full space-y-2">
        {slices.map(s => (
