const LAST = ['García', 'Martín', 'López', 'Navarro', 'Ruiz', 'Serrano', 'Molina', 'Ortega', 'Castillo', 'Rubio', 'Iglesias', 'Medina', 'Garrido', 'Vidal', 'Cano', 'Prieto', 'Lozano', 'Herrera', 'Peña', 'Soler', 'Campos', 'Vega', 'Fuentes', 'Pascual'];
export const CITIES = ['Madrid', 'Barcelona', 'Valencia', 'Sevilla', 'Bilbao', 'Zaragoza', 'Málaga', 'Granada', 'Valladolid', 'A Coruña', 'Palma', 'Alicante', 'Gijón', 'Pamplona'];
const FEATURED: Array<[string, string]> = [['Marta Iglesias', 'persona-1'], ['Pablo Navarro', 'persona-2'], ['Andrés Castillo', 'persona-3'], ['Irene Soler', 'persona-4']];

/** Generador pseudoaleatorio con semilla fija (mulberry32): mismos datos en cada carga. */
export function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const strip = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

export function makeCustomers(count: number): Customer[] {
  const r = rng(7);
  const used = new Set<string>();
  const out: Customer[] = [];
  while (out.length < count) {
    const f = FIRST[Math.floor(r() * FIRST.length)];
    const l = LAST[Math.floor(r() * LAST.length)];
    const i = out.length;
    const feat = FEATURED[i];
    let name = feat ? feat[0] : `${f} ${l}`;
    if (used.has(name)) name += ` ${LAST.filter(x => x !== l)[Math.floor(r() * (LAST.length - 1))]}`;
    if (used.has(name)) continue;
    used.add(name);
    const [fn, ln] = name.split(' ');
    out.push({
      id: `c${i + 1}`, name, city: CITIES[Math.floor(r() * CITIES.length)],
      email: `${strip(fn)}.${strip(ln)}${r() > 0.6 ? Math.floor(r() * 90 + 10) : ''}@${r() > 0.35 ? 'gmail.com' : 'outlook.es'}`,
      since: 180 + Math.floor(r() * 500), avatar: feat ? feat[1] : undefined,
    });
  }
  return out;
}

import { rng, makeCustomers, PRODUCTS, type Channel, type Order, type OrderItem, type Status } from './catalog';

export const DAY = 86_400_000;
export const HISTORY_DAYS = 180;
/** Medianoche de hoy: todos los datos de ejemplo se anclan a esta fecha. */
export const TODAY = (() => { const d = new Date(); d.setHours(0, 0, 0, 0); return d.getTime(); })();

const NOW = Date.now();
export const CUSTOMERS = makeCustomers(2500);

// Peso de cada hora del día en los pedidos (madrugada tranquila, picos a media mañana y por la noche)
const HOUR_W = [1, 0.6, 0.4, 0.3, 0.3, 0.5, 1, 2, 3, 3.5, 4, 4, 4.5, 4.5, 4, 3.5, 3.5, 4, 4.5, 5, 5, 4.5, 3.5, 2];
const HOURS = HOUR_W.map((w, h) => [h, w] as [number, number]);
const nowH = (NOW - TODAY) / 3_600_000;
/** Parte del tráfico diario que ya ha pasado hoy (para comparar periodos en igualdad). */
export const DAY_SHARE = HOUR_W.reduce((s, w, h) => s + w * Math.max(0, Math.min(1, nowH - h)), 0) / HOUR_W.reduce((a, b) => a + b, 0);

const CHANNEL_W: Array<[Channel, number]> = [['web', 0.46], ['instagram', 0.22], ['marketplace', 0.18], ['email', 0.14]];

function pick<T>(r: () => number, list: Array<[T, number]>): T {
  const total = list.reduce((s, [, w]) => s + w, 0);
  let x = r() * total;
  for (const [v, w] of list) { x -= w; if (x <= 0) return v; }
  return list[list.length - 1][0];
}

function statusFor(r: () => number, age: number): Status {
  if (r() < 0.035 && age > 3) return 'reembolsado';
  if (age === 0) return pick(r, [['pendiente', 0.18], ['preparando', 0.62], ['enviado', 0.2]]);
  if (age === 1) return pick(r, [['pendiente', 0.05], ['preparando', 0.35], ['enviado', 0.6]]);
  if (age <= 4) return pick(r, [['preparando', 0.08], ['enviado', 0.52], ['entregado', 0.4]]);
  return 'entregado';
}

/** Pedidos y sesiones de los últimos 180 días, generados con semilla fija. */
function generate() {
  const r = rng(20261);
  const orders: Order[] = [];
  const sessions: number[] = []; // sessions[age] = visitas del día hace `age` días
  const prodW = PRODUCTS.map(p => [p, p.weight] as [typeof PRODUCTS[number], number]);
  let seq = 18240;
  for (let age = HISTORY_DAYS - 1; age >= 0; age--) {
    const date = new Date(TODAY - age * DAY);
    const wd = date.getDay();
    const trend = 1 + ((HISTORY_DAYS - age) / HISTORY_DAYS) * 0.38;
    const week = [0.78, 1.18, 1.06, 1.0, 0.98, 1.04, 0.84][wd];
    const promo = age % 30 === 12 ? 1.6 : 1; // pico de newsletter mensual
    const full = Math.max(6, Math.round(19 * trend * week * promo * (0.82 + r() * 0.36)));
    const stamps = Array.from({ length: full }, () => TODAY - age * DAY + (pick(r, HOURS) + r()) * 3_600_000)
      .filter(ts => ts <= NOW).sort((a, b) => a - b); // hoy solo hasta la hora actual
    const n = stamps.length;
    const conv = 0.021 + r() * 0.006 + (trend - 1) * 0.008;
    sessions[age] = Math.round((full / conv) * (age === 0 ? DAY_SHARE : 1));
    for (let k = 0; k < n; k++) {
      const lines = r() < 0.58 ? 1 : r() < 0.8 ? 2 : 3;
      const items: OrderItem[] = [];
      for (let l = 0; l < lines; l++) {
        const p = pick(r, prodW);
        if (items.some(i => i.productId === p.id)) continue;
        const qty = p.category === 'Café' && r() < 0.35 ? 2 : 1;
        items.push({ productId: p.id, name: p.name, qty, price: p.price });
      }
      const sub = items.reduce((s, i) => s + i.qty * i.price, 0);
      const discount = promo > 1 && r() < 0.5 ? Math.round(sub * 0.1 * 100) / 100 : 0;
      const shipping = sub >= 40 ? 0 : 4.9;
      const ci = Math.floor(Math.pow(r(), 1.4) * CUSTOMERS.length);
      orders.push({
        id: `PU-${seq++}`, ts: Math.floor(stamps[k]),
        customerId: CUSTOMERS[ci].id, items, shipping, discount,
        total: Math.round((sub - discount + shipping) * 100) / 100,
        channel: promo > 1 && r() < 0.5 ? 'email' : pick(r, CHANNEL_W), status: statusFor(r, age),
      });
    }
  }
  return { orders: orders.reverse(), sessions };
}

