const group = (int: string) => int.replace(/\B(?=(\d{3})+(?!\d))/g, '.');

/** 1234.5 → "1.234,50 €" (agrupa también los miles de 4 cifras). */
export function money(n: number, decimals = 2): string {
  const neg = n < 0;
  const [i, d] = Math.abs(n).toFixed(decimals).split('.');
  return `${neg ? '−' : ''}${group(i)}${d ? ',' + d : ''} €`;
}

/** Importe compacto para ejes y tarjetas: 12.400 € → "12,4 k€". */
export function moneyShort(n: number): string {
  if (Math.abs(n) >= 1000) return `${(n / 1000).toFixed(n >= 100_000 ? 0 : 1).replace('.', ',')} k€`;
  return `${Math.round(n)} €`;
}

export const num = (n: number) => group(Math.round(n).toString());
export const pct = (n: number, d = 1) => `${(n * 100).toFixed(d).replace('.', ',')} %`;

const MONTHS = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sept', 'oct', 'nov', 'dic'];
const WEEK = ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'];

export const shortDate = (ts: number) => { const d = new Date(ts); return `${d.getDate()} ${MONTHS[d.getMonth()]}`; };
export const weekDate = (ts: number) => { const w = WEEK[new Date(ts).getDay()]; return `${w[0].toUpperCase()}${w.slice(1)} ${shortDate(ts)}`; };
export const time = (ts: number) => new Date(ts).toTimeString().slice(0, 5);

/** Fecha relativa en español: "hace 12 min", "ayer, 18:40", "hace 5 días", "3 mar". */
export function relative(ts: number): string {
  const diff = Date.now() - ts;
  if (diff < 60_000) return 'ahora mismo';
  if (diff < 3_600_000) return `hace ${Math.floor(diff / 60_000)} min`;
  if (ts >= TODAY) return `hoy, ${time(ts)}`;
  if (ts >= TODAY - DAY) return `ayer, ${time(ts)}`;
  const days = Math.ceil((TODAY - ts) / DAY);
  if (days < 7) return `hace ${days} días`;
  return shortDate(ts);
}

export const initials = (name: string) => name.split(' ').map(w => w[0]).slice(0, 2).join('').toUpperCase();

import { CHANNELS, type Channel, type Order } from '../data/catalog';
import { DAY, DAY_SHARE, TODAY } from '../data/generate';

export type Period = 7 | 30 | 90;
export type DayPoint = { ts: number; revenue: number; orders: number; sessions: number };

const counts = (o: Order) => o.status !== 'reembolsado';

/** Pedidos dentro de los `days` días que terminan hace `offset` días (hoy incluido cuando offset = 0). */
export function inPeriod(orders: Order[], days: number, offset = 0): Order[] {
  const end = TODAY + DAY - offset * DAY;
  const start = end - days * DAY;
  return orders.filter(o => o.ts >= start && o.ts < end);
}

export function periodStats(orders: Order[], sessions: number[], days: number, offset = 0) {
  // El periodo anterior se corta a la misma hora que hoy para comparar en igualdad
  const cut = Date.now() - offset * DAY;
  const list = inPeriod(orders, days, offset).filter(o => !offset || o.ts <= cut);
  const daily: DayPoint[] = [];
  for (let i = days - 1; i >= 0; i--) {
    const age = i + offset;
    const share = offset && age === offset ? DAY_SHARE : 1;
    daily.push({ ts: TODAY - age * DAY, revenue: 0, orders: 0, sessions: Math.round((sessions[age] ?? 0) * share) });
  }
  let revenue = 0, valid = 0;
  for (const o of list) {
    if (!counts(o)) continue;
    revenue += o.total; valid++;
    const age = Math.round((TODAY - new Date(o.ts).setHours(0, 0, 0, 0)) / DAY);
    const idx = days - 1 - (age - offset);
    if (daily[idx]) { daily[idx].revenue += o.total; daily[idx].orders++; }
  }
  const sess = daily.reduce((s, d) => s + d.sessions, 0);
  return {
    list, daily, revenue, orders: valid,
    aov: valid ? revenue / valid : 0,
    conversion: sess ? valid / sess : 0,
    refunds: list.length - valid,
  };
}

export type Stats = ReturnType<typeof periodStats>;

export const delta = (now: number, before: number) => (before ? (now - before) / before : 0);

export function productRanking(list: Order[]) {
  const map = new Map<string, { id: string; name: string; units: number; revenue: number }>();
  for (const o of list) {
    if (!counts(o)) continue;
    for (const it of o.items) {
      const row = map.get(it.productId) ?? { id: it.productId, name: it.name, units: 0, revenue: 0 };
      row.units += it.qty; row.revenue += it.qty * it.price;
      map.set(it.productId, row);
    }
  }
  return [...map.values()].sort((a, b) => b.revenue - a.revenue);
}

export function channelShare(list: Order[]) {
  const sums: Record<Channel, number> = { web: 0, instagram: 0, marketplace: 0, email: 0 };
  for (const o of list) if (counts(o)) sums[o.channel] += o.total;
  const total = Object.values(sums).reduce((a, b) => a + b, 0) || 1;
  return (Object.keys(sums) as Channel[])
    .map(k => ({ key: k, label: CHANNELS[k].label, color: CHANNELS[k].color, value: sums[k], share: sums[k] / total }))
    .sort((a, b) => b.value - a.value);
}

export type Segment = 'VIP' | 'Recurrente' | 'Nuevo' | 'En riesgo' | 'Sin compras';
export type CustomerStat = { count: number; spent: number; last: number; first: number };

export function customerStats(orders: Order[]) {
  const map = new Map<string, CustomerStat>();
  for (const o of orders) {
    if (!counts(o)) continue;
    const s = map.get(o.customerId) ?? { count: 0, spent: 0, last: 0, first: Infinity };
    s.count++; s.spent += o.total; s.last = Math.max(s.last, o.ts); s.first = Math.min(s.first, o.ts);
    map.set(o.customerId, s);
  }
  return map;
}

export function segmentOf(s?: CustomerStat): Segment {
  if (!s || !s.count) return 'Sin compras';
  if (TODAY - s.last > 60 * DAY) return 'En riesgo';
  if (s.spent >= 250) return 'VIP';
  if (s.count >= 3) return 'Recurrente';
  return 'Nuevo';
}

export const SEGMENT_STYLE: Record<Segment, string> = {
  VIP: 'bg-[#FBF1DC] text-[#7A5208]',
  Recurrente: 'bg-[#E2F2EA] text-[#1F5E47]',
  Nuevo: 'bg-[#E7ECFC] text-[#2B44A8]',
  'En riesgo': 'bg-[#FBE7EA] text-[#8E1F33]',
  'Sin compras': 'bg-[#ECEEF2] text-[#4A5261]',
};

import { useEffect, useMemo, useState } from 'react';
import { PRODUCTS, type Customer, type Order, type Product, type Status } from '../data/catalog';
import { BASE, CUSTOMERS } from '../data/generate';
import type { Period } from './metrics';

const KEY = 'pulso-ventas-v1';

type Saved = {
  overrides: Record<string, { status?: Status; note?: string }>;
  extraOrders: Order[];
  products: Product[];
  extraCustomers: Customer[];
};

const fresh = (): Saved => ({ overrides: {}, extraOrders: [], products: PRODUCTS, extraCustomers: [] });

function load(): Saved {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) return { ...fresh(), ...JSON.parse(raw) };
  } catch { /* almacenamiento no disponible */ }
  return fresh();
}

/** Estado de la tienda: datos de ejemplo + cambios del usuario guardados en localStorage. */
export function useStore() {
  const [saved, setSaved] = useState<Saved>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(saved)); } catch { /* sin espacio */ }
  }, [saved]);

  const orders = useMemo(() => {
    const all = [...saved.extraOrders, ...BASE.orders].map(o => {
      const ov = saved.overrides[o.id];
      return ov ? { ...o, ...ov } : o;
    });
    return all.sort((a, b) => b.ts - a.ts);
  }, [saved.extraOrders, saved.overrides]);

  const customers = useMemo(() => [...saved.extraCustomers, ...CUSTOMERS], [saved.extraCustomers]);

  const patch = (fn: (s: Saved) => Saved) => setSaved(s => fn(s));

  return {
    orders, customers, products: saved.products, sessions: BASE.sessions,
    updateOrder: (id: string, change: { status?: Status; note?: string }) =>
      patch(s => ({ ...s, overrides: { ...s.overrides, [id]: { ...s.overrides[id], ...change } } })),
    addOrder: (o: Order) => patch(s => ({ ...s, extraOrders: [o, ...s.extraOrders] })),
    deleteOrder: (id: string) => patch(s => ({ ...s, extraOrders: s.extraOrders.filter(o => o.id !== id) })),
    saveProduct: (p: Product) => patch(s => ({
      ...s, products: s.products.some(x => x.id === p.id) ? s.products.map(x => (x.id === p.id ? p : x)) : [...s.products, p],
    })),
    deleteProduct: (id: string) => patch(s => ({ ...s, products: s.products.filter(p => p.id !== id) })),
    addCustomer: (c: Customer) => patch(s => ({ ...s, extraCustomers: [c, ...s.extraCustomers] })),
    reset: () => setSaved(fresh()),
  };
}

export type Store = ReturnType<typeof useStore>;

export type ViewProps = {
  store: Store;
  period: Period;
  openOrder: (id: string) => void;
  notify: (msg: string) => void;
};
